{"command": "
mkdir -p subsys/rtio && \
echo "/*
 * Copyright (c) 2023 Nordic Semiconductor ASA
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <zephyr/kernel.h>
#include <zephyr/init.h>
#include <zephyr/rtio/rtio.h>
#include <zephyr/rtio/work.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(rtio_workq, CONFIG_RTIO_WORKQ_LOG_LEVEL);

#define RTIO_WORK_QUEUE_MEDIUM_PRIORITY K_PRIO_PREEMPT(8)

K_KERNEL_STACK_ARRAY_DEFINE(rtio_workq_stacks, CONFIG_RTIO_WORKQ_THREADS_POOL,
			    CONFIG_RTIO_WORKQ_STACK_SIZE);

struct k_work_q rtio_workq;

static struct k_mempool rtio_work_req_pool;

void rtio_work_submit(struct rtio *r, struct rtio_iodev_sqe *sqe,
		      k_work_handler_t handler)
{
	struct rtio_work *work = CONTAINER_OF(sqe, struct rtio_work, sqe);

	work->sqe = sqe;
	work->r = r;

	k_work_init(&work->work, handler);
	k_work_submit_to_queue(&rtio_workq, &work->work);
}

static void rtio_work_req_handler(struct k_work *work)
{
	struct rtio_work_req *req = CONTAINER_OF(work, struct rtio_work_req, work_item.work);

	if (req->callback != NULL) {
		req->callback(req->work_item.r, req->work_item.sqe, 0);
	}

	k_mempool_free(&rtio_work_req_pool, req);
}

void rtio_workq_submit(struct rtio_work_req *req,
			rtio_submit_async_callback_t callback, void *arg)
{
	req->callback = callback;
	req->arg = arg;

	k_work_init(&req->work_item.work, rtio_work_req_handler);
	k_work_submit_to_queue(&rtio_workq, &req->work_item.work);
}

struct rtio_work_req *rtio_work_req_alloc(struct rtio *r,
					  struct rtio_iodev_sqe *sqe,
					  size_t data_len)
{
	struct rtio_work_req *req = k_mempool_malloc(&rtio_work_req_pool, K_NO_WAIT);

	if (req == NULL) {
		return NULL;
	}

	req->work_item.r = r;
	req->work_item.sqe = sqe;
	req->data_len = data_len;

	return req;
}

void rtio_work_req_submit(struct rtio_work_req *req)
{
	k_work_submit_to_queue(&rtio_workq, &req->work_item.work);
}


static int rtio_workq_init(void)
{
	k_work_q_init(&rtio_workq);

	for (int i = 0; i < CONFIG_RTIO_WORKQ_THREADS_POOL; i++) {
		k_thread_create(&rtio_workq.threads[i],
				rtio_workq_stacks[i],
				K_KERNEL_STACK_SIZEOF(rtio_workq_stacks[i]),
				k_work_q_main,
				&rtio_workq,
				NULL, NULL,
				RTIO_WORK_QUEUE_MEDIUM_PRIORITY,
				0, K_NO_WAIT);
		k_thread_name_set(&rtio_workq.threads[i], "rtio_workq_%d", i);
	}

	k_mempool_init(&rtio_work_req_pool,
		       CONFIG_RTIO_WORKQ_STACK_SIZE,
		       sizeof(struct rtio_work_req),
		       CONFIG_RTIO_WORKQ_THREADS_POOL,
		       "rtio_work_req_pool");

	return 0;
}

SYS_INIT(rtio_workq_init, APPLICATION, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT);
" > subsys/rtio/rtio_workq.c
"}

