sed -i '/static int akm09918c_submit_async(struct rtio *r, struct rtio_iodev_sqe *sqe)/{
	struct akm09918c_data *data = sqe->iodev->data;
	struct rtio_work_req *req;
	int ret;

	uint8_t *buffer = NULL;
	size_t buffer_len = 0;

	buffer = rtio_sqe_get_mempool_data(sqe, &buffer_len);
	if (buffer == NULL) {
		LOG_ERR("Failed to get mempool data");
		return -ENOMEM;
	}

	req = rtio_work_req_alloc(r, sqe, buffer_len);
	if (req == NULL) {
		LOG_ERR("Failed to allocate work req");
		return -ENOMEM;
