	memcpy(req->data, buffer, buffer_len);

	ret = i2c_read_dt(&data->i2c, req->data, buffer_len);
	if (ret < 0) {
		k_mempool_free(&rtio_work_req_pool, req);
		LOG_ERR("I2C read failed: %d", ret);
		return ret;
	}

	rtio_work_req_submit(req);

	return 0;
}
' drivers/sensor/asahi_kasei/akm09918c/akm09918c_async.c

